<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useProject } from '@/composables/useProject'
import { repository } from '@/data/database'
import { isSimplePolygon, polygonArea, transformPoint } from '@/domain/geometry'
import { floorplanSVG } from '@/services/floorplan'
import { deliverFile } from '@/services/files'
import { areaLabel, lengthLabel } from '@/composables/useSettings'
import { toast } from '@/composables/useToasts'
import { AppError, type Vec3 } from '@/domain/types'
import { errorMessage } from '@/domain/validation'
import AppIcon from '@/components/AppIcon.vue'
import PageHeading from '@/components/PageHeading.vue'
import SceneViewer from '@/components/SceneViewer.vue'
import NoticeBox from '@/components/NoticeBox.vue'
const route = useRoute(), id = computed(() => String(route.params.id)), { project, scenes, loading, error, reload } = useProject(id), tracing = ref(false), selected = ref(''), points = ref<Vec3[]>([]), name = ref(''), height = ref(2.7), floor = ref(0), coordinateText = ref(''), busy = ref(false), floorFilter = ref('all')
watch(project, p => { if (p && !selected.value) selected.value = p.scenes[0]?.id || '' })
const svg = computed(() => { if (!project.value?.rooms.length) return ''; try { return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(floorplanSVG(project.value, floorFilter.value === 'all' ? undefined : Number(floorFilter.value))) } catch { return '' } })
const floors = computed(() => [...new Set(project.value?.rooms.map(r => r.floor) || [])].sort((a,b) => a-b))
function hit(hit: { sceneId: string; position: Vec3 }): void { if (hit.sceneId !== selected.value || !tracing.value || points.value.length >= 100) return; points.value.push([hit.position[0], points.value[0]?.[1] ?? hit.position[1], hit.position[2]]) }
function coordinates(): void { try { const values = coordinateText.value.trim().split('\n').map(line => line.trim().split(/[,\s]+/).map(Number)); if (values.length < 3 || values.length > 100 || values.some(v => v.length !== 2 || v.some(n => !Number.isFinite(n) || Math.abs(n) > 10000))) throw new AppError('Enter 3–100 lines, each containing X,Z coordinates in local metres.'); const polygon = values.map(v => [v[0], 0, v[1]] as Vec3); if (!isSimplePolygon(polygon)) throw new AppError('The outline must not cross itself or contain duplicate corners.'); points.value = polygon } catch (e) { toast(errorMessage(e), 'error') } }
async function save(): Promise<void> { if (!project.value || busy.value) return; busy.value = true; try { if (!selected.value || !name.value.trim() || !isSimplePolygon(points.value)) throw new AppError('Choose a section, name the room and trace at least three non-crossing corners.'); const next = structuredClone(project.value); next.rooms.push({ id: crypto.randomUUID(), sceneId: selected.value, name: name.value.trim(), floor: floor.value, height: height.value, polygon: JSON.parse(JSON.stringify(points.value)), provenance: 'manual' }); await repository.save(next, project.value.revision); points.value = []; tracing.value = false; name.value = ''; await reload(); toast('Room outline saved.', 'success') } catch (e) { toast(errorMessage(e), 'error') } finally { busy.value = false } }
async function remove(roomId: string): Promise<void> { if (!project.value || !confirm('Remove this room outline? The original scan will not change.')) return; try { await repository.save({ ...project.value, rooms: project.value.rooms.filter(r => r.id !== roomId) }, project.value.revision); await reload() } catch (e) { toast(errorMessage(e), 'error') } }
async function exportPlan(): Promise<void> { if (!project.value) return; try { await deliverFile(new Blob([floorplanSVG(project.value, floorFilter.value === 'all' ? undefined : Number(floorFilter.value))], { type: 'image/svg+xml' }), `${project.value.name}-floorplan.svg`); toast('Floor plan export prepared.', 'success') } catch (e) { toast(errorMessage(e), 'error') } }
</script>
<template><div class="container"><PageHeading :back="`/projects/${id}`" eyebrow="MAKE SENSE OF THE SPACE" title="Your floor plan." subtitle="Room outlines with context. No invented walls or dimensions."><button class="btn btn-outline-primary" :disabled="!project?.rooms.length" @click="exportPlan"><AppIcon name="download" :size="18"/>Export SVG</button></PageHeading><NoticeBox v-if="error" kind="error">{{ error }}</NoticeBox><div v-if="loading" class="loading-state">Opening room outlines…</div><template v-if="project"><NoticeBox>Floor plans here use room outlines you deliberately trace, not automatic AI room detection. Measurements are approximate and are not survey or construction drawings.</NoticeBox><div class="floorplan-layout"><div class="card floorplan-canvas"><SceneViewer v-if="tracing" :scenes="scenes" mode="top" :pick="true" :selected-scene-id="selected" :pending-points="points" @pick="hit"/><img v-else-if="svg" :src="svg" :alt="`${project.name} approximate floor plan`"><div v-else class="empty-state"><AppIcon name="map" :size="56"/><h2>A clear outline starts with you.</h2><p>Trace visible floor corners in the top-down model, or enter known X,Z coordinates.</p><button class="btn btn-primary" :disabled="!scenes.length" @click="tracing = true"><AppIcon name="plus"/>Trace your first room</button><RouterLink v-if="!scenes.length" :to="`/projects/${id}/scan`">Capture a section first</RouterLink></div></div><aside class="card detail-card"><div class="section-heading"><h2>{{ tracing ? 'Trace a room' : 'Room outlines' }}</h2><button v-if="!tracing" class="icon-button" :disabled="!scenes.length" aria-label="Trace another room" @click="tracing = true"><AppIcon name="plus"/></button></div><template v-if="tracing"><label class="form-label" for="floor-section">Scan section</label><select id="floor-section" v-model="selected" class="form-select" @change="points = []"><option v-for="s in project.scenes" :key="s.id" :value="s.id">{{ s.name }}</option></select><p class="fine-print mt-2">Tap floor corners in order. Keep the outline on a single horizontal floor.</p><label class="form-label" for="room-name">Room name</label><input id="room-name" v-model="name" class="form-control" maxlength="100" placeholder="e.g. Living room"><div class="row g-2 mt-1"><label class="col-6 form-label">Floor number<input v-model.number="floor" class="form-control" type="number" min="-10" max="200" step="1"></label><label class="col-6 form-label">Height · metres<input v-model.number="height" class="form-control" type="number" min="0.1" max="20" step="0.1"></label></div><div class="stat-pair"><span>Corners selected</span><strong>{{ points.length }}</strong></div><div v-if="points.length >= 3" class="stat-pair"><span>Approximate area</span><strong>{{ areaLabel(polygonArea(points) * (project.scenes.find(s => s.id === selected)?.transform.scale || 1) ** 2) }}</strong></div><button class="text-link" :disabled="!points.length" @click="points.pop()"><AppIcon name="undo" :size="16"/>Undo last corner</button><details class="mt-3"><summary>Enter coordinates instead</summary><p class="fine-print">One local X,Z pair per line, in metres. Example: 0,0 then 4,0 then 4,3 then 0,3.</p><textarea v-model="coordinateText" class="form-control" rows="5" aria-label="Room corner coordinates" placeholder="0,0&#10;4,0&#10;4,3&#10;0,3"/><button class="btn btn-outline-primary btn-sm mt-2" @click="coordinates">Use coordinates</button></details><button class="btn btn-primary w-100 mt-4" :disabled="busy || !name.trim() || !isSimplePolygon(points)" @click="save">{{ busy ? 'Saving…' : 'Save room outline' }}</button><button class="btn btn-outline-secondary w-100 mt-2" @click="tracing = false; points = []">Cancel tracing</button></template><template v-else><label class="form-label" for="floor-filter">Show floor</label><select id="floor-filter" v-model="floorFilter" class="form-select"><option value="all">All floors · may overlap</option><option v-for="f in floors" :key="f" :value="String(f)">Floor {{ f }}</option></select><div v-for="r in project.rooms.filter(r => floorFilter === 'all' || r.floor === Number(floorFilter))" :key="r.id" class="room-row"><span class="row-icon"><AppIcon name="map" :size="21"/></span><div><strong>{{ r.name }}</strong><small>Floor {{ r.floor }} · ≈ {{ areaLabel(polygonArea(r.polygon.map(p => transformPoint(p, project.scenes.find(s => s.id === r.sceneId)!.transform)))) }}<br>Height ≈ {{ lengthLabel(r.height * project.scenes.find(s => s.id === r.sceneId)!.transform.scale) }}</small></div><button class="icon-button" :aria-label="`Remove ${r.name} outline`" @click="remove(r.id)"><AppIcon name="trash" :size="17"/></button></div><p v-if="!project.rooms.length" class="muted mt-3">No room outlines have been saved.</p></template></aside></div></template></div></template>
